"use server"

import prisma from "../../../../prisma/prisma";

function buildCentroFiltro(centros?: string[]) {
    if (!centros || centros.length === 0) return undefined;
    return { in: centros };
}

// Contar funcionários
export async function contarFuncionarios(centros?: string[]) {
    return await prisma.tbFuncionario.count({
        where: buildCentroFiltro(centros) ? { idCustoFun: buildCentroFiltro(centros) } : undefined
    });
}

// Contar funcionários por status
export async function funcionariosPorStatus(centros?: string[]) {
    return await prisma.tbStatusFun.findMany({
        include: {
            tbFuncionario: {
                where: buildCentroFiltro(centros) ? { idCustoFun: buildCentroFiltro(centros) } : undefined,
                select: {
                    idF: true
                }
            }
        }
    });
}

// Contar funcionários por centro de custo
export async function funcionariosPorCentroCusto(centros?: string[]) {
    return await prisma.tbCCusto.findMany({
        where: buildCentroFiltro(centros) ? { idCCusto: buildCentroFiltro(centros) } : undefined,
        select: {
            idCCusto: true,
            descricaoCCusto: true,
            tbFuncionario: {
                select: {
                    idF: true
                }
            }
        }
    });
}

// Contar alocações de patrimônio por centro de custo (total simples - compatível com chamadas existentes)
export async function alocacoesPorCentroCusto(centros?: string[]) {
    const centrosFiltro = buildCentroFiltro(centros);
    const centrosDb = await prisma.tbCCusto.findMany({
        where: centrosFiltro ? { idCCusto: centrosFiltro } : undefined,
        select: {
            idCCusto: true,
            descricaoCCusto: true,
            codigoCCusto: true,
            tbPatrimonio: {
                select: {
                    idP: true,
                    tbTipoPat: {
                        select: {
                            descricaoTipPat: true
                        }
                    },
                    tbCadastro: {
                        select: {
                            idCad: true
                        }
                    }
                }
            }
        }
    });

    return centrosDb.map(centro => {
        const resultado: Record<string, any> = {
            nome: centro.descricaoCCusto || centro.idCCusto,
        };

        // Agrupar por tipo de patrimônio
        const tiposCont: Record<string, number> = {};
        centro.tbPatrimonio.forEach(pat => {
            const tipoNome = pat.tbTipoPat?.descricaoTipPat || 'Sem Tipo';
            const quantidade = pat.tbCadastro.length;
            tiposCont[tipoNome] = (tiposCont[tipoNome] || 0) + quantidade;
        });

        // Adicionar contagens por tipo ao resultado
        Object.assign(resultado, tiposCont);

        return resultado;
    });
}

// Alocações por centro de custo e por tipo de patrimônio (para gráfico de barras com tipo e custo)
export async function alocacoesPorCentroCustoETipo(centros?: string[]) {
    const centrosFiltro = buildCentroFiltro(centros);
    const centrosDb = await prisma.tbCCusto.findMany({
        where: centrosFiltro ? { idCCusto: centrosFiltro } : undefined,
        select: {
            idCCusto: true,
            descricaoCCusto: true,
            codigoCCusto: true,
            tbPatrimonio: {
                select: {
                    idP: true,
                    tbTipoPat: {
                        select: { descricaoTipPat: true }
                    },
                    tbCadastro: {
                        select: { idCad: true }
                    }
                }
            }
        }
    });

    const tiposSet = new Set<string>();
    const porCentro: Record<string, Record<string, number>> = {};

    for (const centro of centrosDb) {
        const nomeCentro = centro.descricaoCCusto || centro.codigoCCusto || centro.idCCusto;
        if (!porCentro[nomeCentro]) porCentro[nomeCentro] = {};

        for (const pat of centro.tbPatrimonio) {
            const tipo = pat.tbTipoPat?.descricaoTipPat?.trim() || 'Sem tipo';
            tiposSet.add(tipo);
            const qtd = pat.tbCadastro.length;
            porCentro[nomeCentro][tipo] = (porCentro[nomeCentro][tipo] || 0) + qtd;
        }
    }

    const tiposOrdenados = Array.from(tiposSet).sort();
    const data = Object.entries(porCentro).map(([nome, contagem]) => {
        const ponto: Record<string, string | number> = { centro: nome };
        for (const tipo of tiposOrdenados) {
            ponto[tipo] = contagem[tipo] || 0;
        }
        return ponto;
    });

    return { data, tipos: tiposOrdenados };
}

// Dados para gráfico de linha (evoluação ao longo do tempo - por mês)
export async function alocacoesAoLongoDoTempo(centros?: string[]) {
    const centrosFiltro = buildCentroFiltro(centros);
    const alocacoes = await prisma.tbCadastro.findMany({
        select: {
            dataCadPat: true
        },
        where: {
            dataCadPat: {
                not: null
            },
            ...(centrosFiltro && {
                tbPatrimonio: {
                    idPat_CustoPat: centrosFiltro
                }
            })
        },
        orderBy: {
            dataCadPat: 'asc'
        }
    });

    const porMes: Record<string, number> = {};
    alocacoes.forEach(aloc => {
        if (aloc.dataCadPat) {
            const data = new Date(aloc.dataCadPat);
            const chave = `${data.getFullYear()}-${String(data.getMonth() + 1).padStart(2, '0')}`;
            porMes[chave] = (porMes[chave] || 0) + 1;
        }
    });

    return Object.entries(porMes)
        .map(([mes, quantidade]) => ({ mes, quantidade }))
        .slice(-12);
}

// Evolução das alocações ao longo do tempo por centro de custo (para gráfico de linha)
export async function alocacoesEvolucaoPorCentroCusto(centros?: string[]) {
    const centrosFiltro = buildCentroFiltro(centros);
    const alocacoes = await prisma.tbCadastro.findMany({
        select: {
            dataCadPat: true,
            idPatCad: true,
            tbPatrimonio: {
                select: {
                    idPat_CustoPat: true,
                    tbCCusto: {
                        select: {
                            idCCusto: true,
                            descricaoCCusto: true,
                            codigoCCusto: true
                        }
                    }
                }
            }
        },
        where: {
            dataCadPat: { not: null },
            ...(centrosFiltro && {
                tbPatrimonio: {
                    idPat_CustoPat: centrosFiltro
                }
            })
        },
        orderBy: {
            dataCadPat: 'asc'
        }
    });

    // porMes[mes][centro] = quantidade
    const porMesCentro: Record<string, Record<string, number>> = {};
    const centrosSet = new Set<string>();

    for (const aloc of alocacoes) {
        if (!aloc.dataCadPat) continue;
        const data = new Date(aloc.dataCadPat);
        const mes = `${data.getFullYear()}-${String(data.getMonth() + 1).padStart(2, '0')}`;
        const centro = aloc.tbPatrimonio?.tbCCusto
            ? (aloc.tbPatrimonio.tbCCusto.descricaoCCusto || aloc.tbPatrimonio.tbCCusto.codigoCCusto || aloc.tbPatrimonio.tbCCusto.idCCusto)
            : 'Sem centro';
        centrosSet.add(centro);
        if (!porMesCentro[mes]) porMesCentro[mes] = {};
        porMesCentro[mes][centro] = (porMesCentro[mes][centro] || 0) + 1;
    }

    const mesesOrdenados = Object.keys(porMesCentro).sort().slice(-12);
    const centrosOrdenados = Array.from(centrosSet).sort();

    const data = mesesOrdenados.map(mes => {
        const ponto: Record<string, string | number> = { mes };
        for (const centro of centrosOrdenados) {
            ponto[centro] = porMesCentro[mes]?.[centro] ?? 0;
        }
        return ponto;
    });

    return { data, centros: centrosOrdenados };
}

export async function resumoCentrosCusto(centros?: string[]) {
    const centrosFiltro = buildCentroFiltro(centros);
    const centrosDb = await prisma.tbCCusto.findMany({
        where: centrosFiltro ? { idCCusto: centrosFiltro } : undefined,
        select: {
            idCCusto: true,
            codigoCCusto: true,
            descricaoCCusto: true,
            _count: {
                select: {
                    tbFuncionario: true
                }
            }
        },
        orderBy: {
            descricaoCCusto: 'asc'
        }
    });

    const centroIds = new Set(centrosDb.map((centro) => centro.idCCusto));
    const cads = await prisma.tbCadastro.findMany({
        select: {
            idPatCad: true,
            dataDevPat: true,
            tbStatusPat: {
                select: {
                    descricaoStatPat: true
                }
            },
            tbFuncionario: {
                select: {
                    idCustoFun: true
                }
            },
            tbPatrimonio: {
                select: {
                    idPat_CustoPat: true
                }
            }
        }
    });

    const ativosPorCentro = new Map<string, Set<string>>();
    const devolvidosPorCentro = new Map<string, number>();
    const transferidosPorCentro = new Map<string, number>();

    for (const cad of cads) {
        const centroId = cad.tbFuncionario?.idCustoFun || cad.tbPatrimonio?.idPat_CustoPat || null;
        if (!centroId || !centroIds.has(centroId)) continue;

        const status = (cad.tbStatusPat?.descricaoStatPat || "").toLowerCase();
        const isTransferido = status.includes("transfer");
        const isAtivo = !cad.dataDevPat && !isTransferido;

        if (isAtivo && cad.idPatCad) {
            if (!ativosPorCentro.has(centroId)) ativosPorCentro.set(centroId, new Set<string>());
            ativosPorCentro.get(centroId)!.add(cad.idPatCad);
        }
        if (isTransferido) {
            transferidosPorCentro.set(centroId, (transferidosPorCentro.get(centroId) || 0) + 1);
        }
    }

    const devolucoes = await prisma.tbDevolucao.findMany({
        select: {
            idDevolucao: true,
            tbCadastro: {
                select: {
                    tbFuncionario: {
                        select: {
                            idCustoFun: true
                        }
                    },
                    tbPatrimonio: {
                        select: {
                            idPat_CustoPat: true
                        }
                    }
                }
            },
            tbPatrimonio: {
                select: {
                    idPat_CustoPat: true
                }
            }
        }
    });

    for (const dev of devolucoes) {
        const centroId =
            dev.tbCadastro?.tbFuncionario?.idCustoFun ||
            dev.tbCadastro?.tbPatrimonio?.idPat_CustoPat ||
            dev.tbPatrimonio?.idPat_CustoPat ||
            null;
        if (!centroId || !centroIds.has(centroId)) continue;
        devolvidosPorCentro.set(centroId, (devolvidosPorCentro.get(centroId) || 0) + 1);
    }

    return centrosDb.map((centro) => ({
        id: centro.idCCusto,
        codigo: centro.codigoCCusto || '',
        nome: centro.descricaoCCusto || centro.codigoCCusto || centro.idCCusto,
        funcionarios: centro._count.tbFuncionario,
        patrimonios: ativosPorCentro.get(centro.idCCusto)?.size || 0,
        ativos: ativosPorCentro.get(centro.idCCusto)?.size || 0,
        devolvidos: devolvidosPorCentro.get(centro.idCCusto) || 0,
        transferidos: transferidosPorCentro.get(centro.idCCusto) || 0,
        // Sem tabela historica de medicao por centro: usa previsao baseada no total de patrimonios.
        previsaoMedicao: ativosPorCentro.get(centro.idCCusto)?.size || 0
    }));
}
